from typing import List
from wordle.types import Feedback


def score_guess(guess: str, target: str) -> List[Feedback):
    """Score a guess against the target word with proper duplicate handling."""
    feedback = [Feedback.MISS] * 5
    guess_counts = _count_letters(guess)
    target_counts = _count_letters(target)
    _mark_hits(guess, target, feedback)
    _mark_presents(guess, target, feedback, guess_counts, target_counts)
    return feedback


def _count_letters(word: str) -> dict[str, int]:
    """Count occurrences of each letter in a word."""
    counts = {}
    for letter in word:
        if letter in counts:
            counts[letter] += 1
        else:
            counts[letter] = 1
    return counts


def _mark_hits(guess: str, target: str, feedback: List[Feedback]) -> None:
    """Mark exact matches (HIT) in the feedback list."""
    for i in range(5):
        if guess[i] == target[i]:
            feedback[i] = Feedback.HIT


def _mark_presents(guess: str, target: str, feedback: List[Feedback], guess_counts: dict[str, int], target_counts: dict[str, int]) -> None:
    """Mark letters present in wrong positions (PRESENT) in the feedback list."""
    for i in range(5):
        if feedback[i] != Feedback.HIT and guess[i] in target and guess_counts[guess[i]] <= target_counts.get(guess[i], 0):
            feedback[i] = Feedback.PRESENT
            target_counts[guess[i]] -= 1

